const input = $json;
const title = String(input.title || '').trim();
const excerpt = String(input.excerpt || '').trim();
const content = String(input.content || '').trim();
const category = String(input.category || '').trim();
const sourceUrl = String(input.source_url || '').trim();

const prompt = [
  'You are an editorial verification assistant for SharedSpace.',
  'Search The Straits Times for recent or relevant stories that are similar to the draft below.',
  'Compare the draft against the matched Straits Times reporting and judge reliability based on corroboration, consistency, sourcing strength, tone, and completeness.',
  '',
  'Scoring guidance:',
  '- factual_accuracy: higher when core claims align with matched Straits Times reporting.',
  '- source_quality: higher when several relevant Straits Times matches are found and used.',
  '- bias_detection: higher when the draft remains balanced and avoids exaggeration.',
  '- logical_consistency: higher when the draft is internally coherent and consistent with matched stories.',
  '- completeness: higher when the draft covers the main who/what/when/where/why details supported by the matched stories.',
  '',
  'If no strong Straits Times match is found, lower source_quality and mention that clearly in the summary and verdict.',
  '',
  `Draft title: ${title}`,
  `Draft category: ${category}`,
  `Draft summary: ${excerpt}`,
  `Reference URL supplied by user: ${sourceUrl || 'None'}`,
  '',
  'Draft content:',
  content
].join('\n');

return [{ json: { ...input, prompt } }];

